{
  "predictors": [
    {
      "name": "R&D Intensity Surprise",
      "construction": "Calculate the year-over-year change in R&D expenditure scaled by total assets, using Compustat data.",
      "rationale": "Unexpected increases in R&D intensity may signal new growth opportunities and innovative potential.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Insider Trading Volume",
      "construction": "Aggregate the absolute volume of insider trades over the past 6 months from SEC Form 4 filings.",
      "rationale": "High insider trading activity may indicate private information about future performance.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Supplier Concentration Risk",
      "construction": "Use 10-K filings to determine the percentage of purchases from top suppliers over the past fiscal year.",
      "rationale": "Dependence on a few suppliers might imply vulnerability to supply chain disruptions and bargaining power issues.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Employee Productivity Growth",
      "construction": "Measure the change in revenue per employee over the past 3 years using Compustat data.",
      "rationale": "Improving productivity can indicate efficiency gains and potential margin expansion.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Dividend Coverage Ratio Change",
      "construction": "Calculate the change in earnings per share divided by dividends per share over the past 2 years.",
      "rationale": "An improving ratio suggests stronger earnings capacity relative to dividend payments, potentially signaling financial health.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Climate Change Preparedness",
      "construction": "Assess the number of mentions of climate change and sustainability initiatives in the annual report compared to the previous year.",
      "rationale": "Firms that proactively address climate risks may better adapt to regulatory and environmental challenges.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Debt Maturity Extension",
      "construction": "Calculate the average maturity of debt in years and track changes over the past year using debt schedules in 10-K filings.",
      "rationale": "Extending debt maturity may indicate improved financial stability and lower refinancing risk.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Track the percentage change in the number of citations received by a firm's patents over the past 3 years from USPTO data.",
      "rationale": "Growth in patent citations may reflect valuable and influential innovations.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Advertising Efficiency",
      "construction": "Calculate the ratio of sales growth to advertising expense growth over the past 2 years.",
      "rationale": "Efficient advertising should lead to higher sales growth for the same or reduced advertising spend.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Management Turnover Frequency",
      "construction": "Count the number of senior management changes over the past 5 years from corporate announcements and filings.",
      "rationale": "Frequent turnover can signal instability and potential strategic misalignment.",
      "higher_returns_for": "Low values of the measure"
    }
  ]
}
